targets.rawSql:
SELECT concat(full_label, '   ', toString(round(pct_billed)), '% · term ', toString(round(pct_term)), '%') AS Line,
               if(status_shown = 'over billed', least(pct_billed, 250), NULL) AS `Over billed`,
               if(status_shown = 'will exceed', least(pct_billed, 250), NULL) AS `Will exceed`,
               if(status_shown = 'renewal risk', least(pct_billed, 250), NULL) AS `Renewal risk`,
               if(status_shown = 'below pace', least(pct_billed, 250), NULL) AS `Below pace`,
               if(status_shown = 'ahead', least(pct_billed, 250), NULL) AS `Ahead`,
               if(status_shown = 'on pace', least(pct_billed, 250), NULL) AS `On pace`,
               if(status_shown = 'too early', least(pct_billed, 250), NULL) AS `Too early to tell`,
               greatest(least(forecast_end_pct, 250) - least(pct_billed, 250), 0) AS `More by the term end (forecast)`
        FROM (SELECT *, if(renewal_risk, 'renewal risk', status) AS status_shown FROM n360.v_contract_status) WHERE account IN (${account:singlequote}) AND status_shown IN (${status:singlequote}) AND pct_billed IS NOT NULL
          AND status_shown NOT IN ('under review', 'billed not recorded', 'unmapped', 'not built', 'not measured', 'not read')
        ORDER BY status_rank, pct_billed DESC
